import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";

export const fps = 25;

const COLORS = {
  orange: "#FF6B35",
  orangeDim: "rgba(255,107,53,0.15)",
  white: "#FFFFFF",
  offWhite: "#F0F0F0",
  gray: "#888888",
  lightGray: "#AAAAAA",
  red: "#FF0000",
  green: "#4CAF50",
  blue: "#2196F3",
  bg: "#080810",
  cardBg: "rgba(255,255,255,0.04)",
  cardBorder: "rgba(255,255,255,0.08)",
};

const TRANSITION = 12;

// ─── Reusable background ──────────────────────────────────────────────────────
const DarkBg: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: "#000000" }} />
);

// ─── Scene 1 · 96 frames ─────────────────────────────────────────────────────
// "YouTube has over 500 hours of video uploaded every minute."
const Scene1: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const numProgress = spring({ frame, fps, delay: 3, config: { damping: 200 } });
  const labelProgress = spring({ frame, fps, delay: 18, config: { damping: 200 } });
  const counter = Math.round(interpolate(numProgress, [0, 1], [0, 500]));

  // orbiting particles
  const PARTICLES = Array.from({ length: 14 }, (_, i) => i);

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <DarkBg />

      {/* Radial glow */}
      <AbsoluteFill
        style={{
          background:
            "radial-gradient(ellipse 1000px 600px at 50% 50%, rgba(255,107,53,0.1) 0%, transparent 70%)",
          opacity: numProgress,
        }}
      />

      {/* Orbit rings */}
      {[800, 1000, 1220].map((size, i) => (
        <div
          key={i}
          style={{
            position: "absolute",
            width: size,
            height: size,
            borderRadius: "50%",
            border: `1px solid rgba(255,107,53,${0.06 - i * 0.015})`,
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)",
          }}
        />
      ))}

      {/* Orbiting dots */}
      {PARTICLES.map((i) => {
        const angle = (i / PARTICLES.length) * Math.PI * 2 + frame * 0.01;
        const r = 400 + (i % 3) * 100;
        const x = Math.cos(angle) * r;
        const y = Math.sin(angle) * r;
        const pProgress = spring({
          frame,
          fps,
          delay: 5 + i * 2,
          config: { damping: 200 },
        });
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              width: i % 4 === 0 ? 20 : 10,
              height: i % 4 === 0 ? 20 : 10,
              borderRadius: "50%",
              backgroundColor:
                i % 4 === 0 ? COLORS.orange : "rgba(255,255,255,0.25)",
              top: "50%",
              left: "50%",
              transform: `translate(calc(-50% + ${x}px), calc(-50% + ${y}px))`,
              opacity: pProgress * 0.6,
            }}
          />
        );
      })}

      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          paddingBottom: 160,
        }}
      >
        {/* Big number */}
        <div
          style={{
            fontSize: 320,
            fontWeight: 900,
            color: COLORS.white,
            lineHeight: 1,
            letterSpacing: "-12px",
            opacity: numProgress,
            transform: `scale(${interpolate(numProgress, [0, 1], [0.55, 1])})`,
          }}
        >
          {counter}
        </div>

        {/* Divider */}
        <div
          style={{
            width: interpolate(labelProgress, [0, 1], [0, 700]),
            height: 3,
            background: `linear-gradient(90deg, transparent, ${COLORS.orange}, transparent)`,
            borderRadius: 2,
            margin: "24px 0",
          }}
        />

        <div
          style={{
            fontSize: 68,
            fontWeight: 600,
            color: COLORS.lightGray,
            letterSpacing: "0.18em",
            textTransform: "uppercase",
            opacity: labelProgress,
            transform: `translateY(${interpolate(
              labelProgress,
              [0, 1],
              [40, 0]
            )}px)`,
          }}
        >
          hours uploaded every minute
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

