                  }}
                />
              </div>
            </div>
          </div>
        </div>

        {/* Right: notification + counter */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: 48,
          }}
        >
          {/* Notification pill */}
          <div
            style={{
              backgroundColor: "rgba(255,255,255,0.05)",
              borderRadius: 28,
