// ─── Duration calculation ─────────────────────────────────────────────────────
// All durations in frames at 25fps matching exact script timestamps:
//
// Black open:   20
// Scene 1:      96   frames  (00:00:00:01 – 00:00:03:22)
// Scene 2:     181   frames  (00:00:03:22 – 00:00:11:03)
// Scene 3:     342   frames  (00:00:11:03 – 00:00:24:20)
// Scene 4:     331   frames  (00:00:24:20 – 00:00:38:01)
// Scene 5:     880   frames  (00:00:38:01 – 00:01:13:06)
// Scene 6:    1398   frames  (00:01:13:06 – 00:02:09:04)
// Scene 7:    2406   frames  (00:02:09:04 – 00:03:44:10)
// Scene 8:    1764   frames  (00:03:44:10 – 00:04:55:24)
// Scene 9:    1393   frames  (00:04:55:24 – 00:05:51:17)
// Black close:  25
//
// 9 scenes → 10 transitions (open→s1, s1→s2, …, s9→close)

const BLACK_OPEN = 20;
const S1 = 96;
const S2 = 181;
const S3 = 342;
const S4 = 331;
const S5 = 880;
const S6 = 1398;
const S7 = 2406;
const S8 = 1764;
const S9 = 1393;
const BLACK_CLOSE = 25;
const T = TRANSITION;
const NUM_TRANSITIONS = 10;

export const durationInFrames =
  BLACK_OPEN +
  S1 + S2 + S3 + S4 + S5 + S6 + S7 + S8 + S9 +
  BLACK_CLOSE -
  NUM_TRANSITIONS * T;

// ─── Main Composition ─────────────────────────────────────────────────────────
const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={BLACK_OPEN}>
        <BlackScreen />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: T })}
      />

      <TransitionSeries.Sequence durationInFrames={S1 + T}>
        <Scene1 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: T })}
      />

      <TransitionSeries.Sequence durationInFrames={S2 + T}>
        <Scene2 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: T })}
      />

      <TransitionSeries.Sequence durationInFrames={S3 + T}>
        <Scene3 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: T })}
      />

      <TransitionSeries.Sequence durationInFrames={S4 + T}>
        <Scene4 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: T })}
      />

      <TransitionSeries.Sequence durationInFrames={S5 + T}>
        <Scene5 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: T })}
      />

      <TransitionSeries.Sequence durationInFrames={S6 + T}>
        <Scene6 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: T })}
      />

      <TransitionSeries.Sequence durationInFrames={S7 + T}>
        <Scene7 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: T })}
      />

      <TransitionSeries.Sequence durationInFrames={S8 + T}>
        <Scene8 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: T })}
      />

      <TransitionSeries.Sequence durationInFrames={S9 + T}>
        <Scene9 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: T })}
      />

      <TransitionSeries.Sequence durationInFrames={BLACK_CLOSE}>
        <BlackScreen />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
